                    "sql": "create or replace table MAPLEMONK.KA_US_BIGCOMMERCE_FACT_ITEMS AS with item_sales as ( select \'US\' REGION, \'WEBSITE US\' AS Shop_name, \'WEBSITE US\' AS marketplace, ORDER_ID, SKU, cast(PRODUCT_ID as string) PRODUCT_ID, fi.NAME PRODUCT_NAME, cast(QUANTITY as float64) quantity, cast(price_ex_tax as float64)*cast(QUANTITY as float64) AS GROSS_SALES_BEFORE_TAX, cast(json_extract_scalar(dis,\'$.amount\') as float64) Discount, json_extract_scalar(dis,\'$.code\') Discount_Code, json_extract_scalar(dis,\'$.name\') Discount_Name, json_extract_scalar(dis,\'$.target\') Discount_Target, cast(price_tax as float64)*cast(QUANTITY as float64) tax, cast(fixed_shipping_cost as float64) Shipping_Price, cast(TOTAL_INC_TAX as float64) AS SELLING_PRICE, id AS SALEORDERITEMCODE, id AS SALES_ORDER_ITEM_ID, case when (is_refunded) = true then 1 else 0 end RETURN_FLAG, cast(quantity_refunded as float64) Refund_Quantity, cast(refund_amount as float64) Refund_Amount, SKU AS SKU_CODE, p.commonsku, upper(coalesce(p.name, fi.Name)) Product_name_final, UPPER(p.Category) AS PRODUCT_CATEGORY, UPPER(p.Sub_Category) AS PRODUCT_SUB_CATEGORY from `MapleMonk.KA_BigCommerce_order_products` fi left join unnest(applied_discounts) dis left join (select COMMONSKUCODE, SKUVaultCode from maplemonk.SKU_SKUVAULT_MAPPING qualify row_number()over (partition by lower(SKUVaultCode) order by 1) = 1 and skuvaultcode = \'KA011 - 001\' ) p1 on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p1.SKUVaultCode,\' \',\'\')) left join (select marketplace_sku skucode, name, category, category_code sub_category, category_code, commonsku, TAX_RATE from maplemonk.final_sku_master qualify row_number()over (partition by lower(commonsku) order by ifnull(commonsku,\'\') desc) = 1 and commonsku = \'KA011 - 001\' ) p on lower(replace(p1.commonskucode,\' \',\'\')) = lower(replace(p.commonsku,\' \',\'\')) ), orders as ( select id reference_code ,upper(status) Order_Status ,datetime(timestamp(date_created) , \"America/Los_Angeles\") ORDER_TIMESTAMP_PST ,datetime(timestamp(date_created), \"Asia/Kolkata\") ORDER_TIMESTAMP_IST ,datetime(timestamp(date_shipped), \"America/Los_Angeles\") ORDER_SHIPPED_DATE_PST ,timestamp(datetime(timestamp(date_shipped)), \"Asia/Kolkata\") ORDER_SHIPPED_DATE_IST ,datetime(timestamp(date_modified), \"America/Los_Angeles\") ORDER_MODIFIED_DATE_PST ,timestamp(datetime(timestamp(date_modified)), \"Asia/Kolkata\") ORDER_MODIFIED_DATE_IST ,upper(coalesce(GA4.channel,orders.order_source)) Channel ,upper(coalesce(GA4.final_source,orders.order_source)) Source ,upper(json_extract_scalar(billing_address, \'$.country\')) Country ,upper(payment_method) payment_method ,upper(payment_status) payment_status ,cast(coupon_discount as float64) Coupon_discount ,cast(discount_amount as float64) Discount_Amount ,cast(store_credit_amount as float64) store_credit_amount ,currency_code ,json_extract_scalar(billing_address, \'$.zip\') Pincode ,upper(concat(json_extract_scalar(billing_address, \'$.first_name\'), json_extract_scalar(billing_address, \'$.last_name\'))) Name ,customer_id ,upper(json_extract_scalar(billing_address, \'$.phone\')) Phone ,upper(json_extract_scalar(billing_address, \'$.email\')) Email ,upper(json_extract_scalar(billing_address, \'$.city\')) City ,upper(json_extract_scalar(billing_address, \'$.state\')) State ,is_email_opt_in from `MapleMonk.KA_BigCommerce_New_orders` Orders LEFT Join ( select transactionid ,Final_Source ,Channel from maplemonk.KA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) = 1 ) GA4 on cast(orders.id as string) = cast(GA4.transactionid as string) ) select fis.* ,fis.Discount*coalesce(CM.USD_INR,83) Discount_INR ,fis.GROSS_SALES_BEFORE_TAX*coalesce(CM.USD_INR,83) GROSS_SALES_BEFORE_TAX_INR ,fis.tax*coalesce(CM.USD_INR,83) Tax_INR ,fis.SELLING_PRICE*coalesce(CM.USD_INR,83) SELLING_PRICE_INR ,fis.Shipping_Price*coalesce(CM.USD_INR,83) Shipping_Price_INR ,fis.refund_amount*coalesce(CM.USD_INR,83) refund_amount_INR ,o.Order_Status ,o.ORDER_TIMESTAMP_PST ,o.ORDER_TIMESTAMP_IST ,o.ORDER_SHIPPED_DATE_PST ,o.ORDER_SHIPPED_DATE_IST ,o.ORDER_MODIFIED_DATE_PST ,o.ORDER_MODIFIED_DATE_IST ,o.Channel ,o.Source ,o.Country ,o.City ,o.State ,o.Pincode ,o.payment_method ,o.payment_status ,safe_divide(cast(o.store_credit_amount as float64), row_number() over (partition by o.reference_code order by 1)) store_credit_amount ,o.currency_code ,o.Name ,o.customer_id ,o.Phone ,o.email ,o.is_email_opt_in from item_sales fis left join orders o on fis.order_id = o.reference_code left join (select PARSE_DATE(\'%Y-%m-%d\', SUBSTR(date, 1, 10)) AS Date ,safe_cast(close as float64) USD_INR from `MapleMonk.USD_INR_Conversion` where PARSE_DATE(\'%Y-%m-%d\', SUBSTR(date, 1, 10)) < \'2024-11-01\' union all select safe_cast(date as date) Date ,safe_divide(safe_cast(JSON_EXTRACT_SCALAR(rates, \'$.INR\') as float64) ,safe_cast(JSON_EXTRACT_SCALAR(rates, \'$.USD\') as float64) ) AS USD_INR from `MapleMonk.KA_exchange_rates` where safe_cast(date as date) >= \'2024-11-01\' ) CM on cast(o.ORDER_TIMESTAMP_IST as date) = CM.date ;",
